// Validate required fields from GHL payment webhook
// Real GHL structure: body.contact_id, body.email, body.order.line_items[0].price,
// body.order.line_items[0].meta.order_id, body.customData.*
const body = $json.body || $json;
const customData = body.customData || {};
const order = body.order || {};
const lineItems = order.line_items || [];
const firstItem = lineItems[0] || {};
const customer = order.customer || {};

// Contact info — top-level body fields, then customData, then order.customer
const contactId = body.contact_id || body.contactId || customData.contact_id || customer.id || '';
const contactEmail = body.email || customData.contact_email || customer.email || '';

// Amount — use line item price (pre-discount deposit value), NOT total_price (post-discount)
let paymentAmount = 0;
if (firstItem.price && parseFloat(firstItem.price) > 0) {
  paymentAmount = parseFloat(firstItem.price);
} else if (order.total_cart_price && parseFloat(order.total_cart_price) > 0) {
  paymentAmount = parseFloat(order.total_cart_price);
} else if (customData.amount && parseFloat(customData.amount) > 0) {
  paymentAmount = parseFloat(customData.amount);
} else if (order.total_price && parseFloat(order.total_price) > 0) {
  paymentAmount = parseFloat(order.total_price);
}

// Payment ID — order_id from line item meta for idempotency
const paymentId = (firstItem.meta && firstItem.meta.order_id) || order.id || customData.appointment_id || body.payment_id || '';

// Appointment / artist info from customData (may be empty — appointment lookup happens later)
const artistName = customData.calendarName || body.calendarName || '';
const appointmentDate = customData.appointment_date || body.appointment_date || '';
const appointmentId = customData.appointment_id || '';

// Product title from line item (e.g. 'Tattoo Deposit - $100 Deposit')
const productTitle = firstItem.title || firstItem.name || '';
const contactName = (body.first_name || '') + ' ' + (body.last_name || '');

// Validation with debug info
if (!contactEmail) {
  throw new Error('Missing contact email. Top-level keys: ' + Object.keys(body).join(', '));
}
if (!paymentAmount || paymentAmount <= 0) {
  throw new Error('Missing or invalid payment amount. order keys: ' + Object.keys(order).join(', ') + ' | lineItem keys: ' + Object.keys(firstItem).join(', ') + ' | customData.amount: ' + customData.amount);
}
if (!paymentId) {
  throw new Error('Missing payment ID. order keys: ' + Object.keys(order).join(', '));
}

return [{
  json: {
    contactId,
    contactEmail,
    contactName: contactName.trim(),
    paymentAmount,
    paymentId: String(paymentId),
    artistName,
    appointmentDate,
    appointmentId,
    productTitle,
    rawPayload: body
  }
}];

// Extract the next upcoming appointment from GET /contacts/{id}/appointments
const response = $json.body || $json;
const statusCode = $json.statusCode || response.statusCode || 0;

// GHL may return appointments under various keys
const events = response.events || response.appointments || response.data || [];

const debugInfo = {
  statusCode,
  responseKeys: Object.keys(response).join(', '),
  eventCount: Array.isArray(events) ? events.length : 'not-array',
  sampleEvent: events.length > 0 ? Object.keys(events[0]).join(', ') : 'none'
};

// If GHL API returned an error, surface it
if (statusCode >= 400) {
  return [{ json: { hasAppointment: false, message: 'GHL appointments API error: HTTP ' + statusCode, debug: debugInfo, apiResponse: response } }];
}

if (!events || !events.length) {
  return [{ json: { hasAppointment: false, message: 'No appointments found for contact', debug: debugInfo } }];
}

// Filter to future appointments only, then sort ascending
const now = new Date();
const future = events.filter(e => {
  const start = new Date(e.startTime || e.start_time || e.selectedTimeslot || '');
  return start > now;
});

if (!future.length) {
  return [{ json: { hasAppointment: false, message: 'No future appointments found (' + events.length + ' total, all in past)', debug: debugInfo } }];
}

const sorted = future.sort((a, b) => new Date(a.startTime || a.start_time) - new Date(b.startTime || b.start_time));
const next = sorted[0];

return [{
  json: {
    hasAppointment: true,
    eventId: next.id,
    calendarId: next.calendarId || next.calendar_id,
    title: next.title || next.name || '',
    startTime: next.startTime || next.start_time,
    status: next.status || next.appointmentStatus || '',
    debug: debugInfo
  }
}];
